    let r = resolve(&ac, "H", "c", &["dry_run__band_a"]);
    assert_eq!(r.page_actions, vec![LIVENESS]);
    for ls in [&["band_a", "band_a"][..], &["band_a", "dry_run__band_a"]] {
        let r = resolve(&ac, "H", "c", ls);
        assert_eq!(
            (r.mode, r.page_actions),
            (ControlMode::Live, vec![LIVENESS]),
            "{ls:?}"
        );
    }
}

